a<-commandArgs(TRUE);stopifnot(length(a)==2);src<-a[1];out<-a[2];if(dir.exists(out))stop('Output exists');dir.create(out,recursive=TRUE)
suppressPackageStartupMessages({library(jsonlite);library(data.table);library(ggplot2);library(patchwork);library(svglite);library(ragg)})
x<-fromJSON(file.path(src,'Search_HSP90AA1.json'),simplifyVector=FALSE);reg<-fread(file.path(src,'entry_manifest.tsv'));ids<-sort(vapply(x,function(z)z$dataset_id,integer(1)))
b<-rbindlist(lapply(x,function(d)rbind(data.table(entry=d$dataset_id,group='Non-cancer',low=d$ctrl_min,q1=d$ctrl_p25,median=d$ctrl_median,q3=d$ctrl_p75,high=d$ctrl_max),data.table(entry=d$dataset_id,group='Cancer',low=d$tumor_min,q1=d$tumor_p25,median=d$tumor_median,q3=d$tumor_p75,high=d$tumor_max))))
s<-rbindlist(lapply(x,function(d)data.table(entry=d$dataset_id,FDR=d$adjusted_pvalue,n_columns=d$analysis_n_control+d$analysis_n_case,n_finite=d$feature_n_control+d$feature_n_case)))
b[,pos:=match(entry,ids)+ifelse(group=='Non-cancer',-.18,.18)];b[,group:=factor(group,levels=c('Non-cancer','Cancer'))];s[,pos:=match(entry,ids)];s[,star:=ifelse(FDR<=.0001,'****',ifelse(FDR<=.001,'***',ifelse(FDR<=.01,'**',ifelse(FDR<=.05,'*','ns'))))]
labs<-vapply(ids,function(i){r<-reg[entry_id==i];paste0(r$accession,'\nID',i,if(r$molecule_layer=='Phosphoprotein')' (P)'else'')},character(1))
font<-'Arial';theme_set(theme_bw(base_size=10,base_family=font)+theme(plot.title=element_text(face='bold',size=10,hjust=.5),plot.tag=element_text(face='bold',size=14),legend.title=element_blank(),legend.text=element_text(size=10),axis.text=element_text(size=9),axis.title=element_text(size=10),plot.margin=margin(3,4,3,4),panel.grid.minor=element_line(colour='#f2f2f2',linewidth=.2),panel.grid.major=element_line(colour='#e1e5eb',linewidth=.3)))
ytop<-max(b$high,na.rm=TRUE)+2.5;ybottom<-min(-6,min(b$low,na.rm=TRUE)-.5)
head<-ggplot()+annotate('rect',xmin=.02,xmax=.98,ymin=.10,ymax=.60,fill='#ededed',colour=NA)+annotate('text',x=.02,y=.91,label='Search results',hjust=0,fontface='bold',size=4.2,family=font)+annotate('text',x=.04,y=.35,label=sprintf('Protein: HSP90AA1    Matrix entries: %d    Finite observations: %d',nrow(s),sum(s$n_finite)),hjust=0,size=3.15,fontface='bold',colour='#202c50',family=font)+xlim(0,1)+ylim(0,1)+theme_void()+labs(tag='A')+theme(plot.tag=element_text(size=14,face='bold'))
pa<-ggplot()+geom_rect(data=data.frame(i=seq_along(ids)),aes(xmin=i-.47,xmax=i+.47,ymin=ybottom,ymax=ytop-.9),fill='#f5f6f8',colour=NA)+geom_boxplot(data=b,aes(x=pos,group=pos,ymin=low,lower=q1,middle=median,upper=q3,ymax=high,fill=group,colour=group),stat='identity',width=.31,alpha=.5,linewidth=.45)+scale_fill_manual(values=c('Non-cancer'='#444d94','Cancer'='#ad3b36'))+scale_colour_manual(values=c('Non-cancer'='#283673','Cancer'='#ad2925'),guide='none')+geom_text(data=s,aes(x=pos,y=ytop-.2,label=star),size=3.3,family=font)+scale_x_continuous(breaks=seq_along(ids),labels=labs,expand=expansion(add=.6))+scale_y_continuous(limits=c(ybottom,ytop+.7))+labs(x=NULL,y='Control-relative z-score',title='Expression Distribution of Protein HSP90AA1')+theme(axis.text.x=element_text(angle=55,hjust=1,size=9),legend.position='top',legend.justification='right')
roc<-fread(file.path(src,'ROC_coordinates.tsv'));stat<-fread(file.path(src,'ROC_summary.tsv'));choice<-c(18,33,20,37,11,47);names<-c('CRC','NB','GBM','BLCA','HCC','MB')
pp<-lapply(seq_along(choice),function(j){id<-choice[j];z<-roc[entry_id==id];q<-stat[entry_id==id];m<-reg[entry_id==id]
 ggplot(z,aes(FPR,TPR))+geom_abline(slope=1,intercept=0,linetype='dashed',colour='#7d8085',linewidth=.35)+geom_path(colour='#9aa6b8',linewidth=.6)+scale_x_continuous(breaks=c(0,.5,1),limits=c(0,1),expand=expansion(add=.035))+scale_y_continuous(breaks=c(0,.5,1),limits=c(0,1),expand=expansion(add=.035))+annotate('text',x=.98,y=.065,label=sprintf('AUC = %.4f',q$apparent_auc),hjust=1,size=3.2,family=font)+labs(x='1 − Specificity',y='Sensitivity',title=paste0(names[j],' (',m$accession,')'),tag=LETTERS[j+1])
})
p<-wrap_plots(wrap_plots(head,pa,ncol=1,heights=c(.32,2.25)),wrap_plots(pp[1:3],ncol=3),wrap_plots(pp[4:6],ncol=3),ncol=1,heights=c(2.57,1.2,1.2))
ggsave(file.path(out,'Figure_5.pdf'),p,width=178/25.4,height=234/25.4,device=cairo_pdf,bg='white');ggsave(file.path(out,'Figure_5.svg'),p,width=178/25.4,height=234/25.4,device=svglite,bg='white');ggsave(file.path(out,'Figure_5.png'),p,width=178,height=234,units='mm',dpi=300,device=agg_png,bg='white')
fwrite(b,file.path(out,'Figure5_box_statistics.tsv'),sep='\t');fwrite(s,file.path(out,'Figure5_entry_statistics.tsv'),sep='\t')
